 33	pub fn unescape(s: &str) -> Result<Vec<u8>> {
 34	    let mut out = Vec::new();
 35	    let mut it = s.bytes();
 36	    while let Some(b) = it.next() {
 37	        if b != b'\\' {
 38	            out.push(b);
 39	            continue;
 40	        }
 41	        match it.next() {
 42	            Some(b't') => out.push(b'\t'),
 43	            Some(b'n') => out.push(b'\n'),
 44	            Some(b'\\') => out.push(b'\\'),
 45	            _ => return Err(Error::Invalid(format!("bad escape in {s:?}"))),
 46	        }
 47	    }
 48	    Ok(out)
 49	}
