 51	/// Resolve an evidence path under `repo_root`, or say why it is refused.
 52	fn resolve_evidence_path(repo_root: &Path, path: &str) -> std::result::Result<PathBuf, String> {
 53	    // Check the raw text: `Path::components` silently drops `.` and empty
 54	    // parts, which would hide `a/./b` and `a//b`.
 55	    if path.is_empty() || path.split('/').any(|c| c.is_empty() || c == "." || c == "..") {
 56	        return Err(format!("{path}: evidence path must be relative, with no '..', '.' or empty components"));
 57	    }
 58	    // No hidden components at any level, compared case-insensitively. This
 59	    // keeps `.git`, `.descartes` (the store and the node key) and `.cargo`
 60	    // out of reach, so a committed claims file cannot test guesses against
 61	    // their bytes. Evidence comes from inventoried, visible files only.
 62	    if path.split('/').any(|c| c.starts_with('.')) {
 63	        return Err(format!("{path}: evidence path may not contain a hidden ('.') component"));
 64	    }
 65	    let rel = Path::new(path);
 66	    if !rel.components().all(|c| matches!(c, Component::Normal(_))) {
 67	        return Err(format!("{path}: evidence path must be relative"));
 68	    }
 69	    // Walk it one component at a time without following anything: a symlink
 70	    // at any level could point outside the repository.
 71	    let mut at = repo_root.to_path_buf();
 72	    for c in rel.components() {
 73	        at.push(c);
 74	        match fs::symlink_metadata(&at) {
 75	            Ok(m) if m.file_type().is_symlink() => return Err(format!("{path}: evidence path goes through a symlink")),
 76	            Ok(_) => {}
 77	            Err(e) => return Err(format!("{path}: cannot read: {e}")),
 78	        }
 79	    }
 80	    // A hard link shares bytes with a file that may live in a hidden
 81	    // directory (the key), and path checks cannot see that. Refuse it.
 82	    #[cfg(unix)]
 83	    {
 84	        use std::os::unix::fs::MetadataExt;
 85	        if fs::symlink_metadata(&at).map(|m| m.nlink() > 1).unwrap_or(false) {
 86	            return Err(format!("{path}: evidence file has more than one hard link"));
 87	        }
 88	    }
 89	    // Belt and braces: the resolved file must still be under the root.
 90	    let root = repo_root.canonicalize().map_err(|e| format!("{}: cannot resolve repository root: {e}", repo_root.display()))?;
 91	    let full = at.canonicalize().map_err(|e| format!("{path}: cannot resolve: {e}"))?;
 92	    if !full.starts_with(&root) {
 93	        return Err(format!("{path}: evidence path resolves outside the repository"));
 94	    }
 95	    Ok(full)
 96	}
