 98	/// SHA-256 digests of the regular files directly in `<repo>/prompts/`.
 99	/// A missing directory is an empty set; symlinks are not followed.
100	fn prompt_file_digests(repo_root: &Path) -> std::result::Result<BTreeSet<String>, String> {
101	    let dir = repo_root.join("prompts");
102	    let mut set = BTreeSet::new();
103	    let entries = match fs::read_dir(&dir) {
104	        Ok(e) => e,
105	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => return Ok(set),
106	        Err(e) => return Err(format!("prompts/: cannot read: {e}")),
107	    };
108	    for entry in entries {
109	        let entry = entry.map_err(|e| format!("prompts/: cannot read: {e}"))?;
110	        let meta = fs::symlink_metadata(entry.path()).map_err(|e| format!("prompts/: cannot read: {e}"))?;
111	        if !meta.is_file() {
112	            continue;
113	        }
114	        let bytes = fs::read(entry.path()).map_err(|e| format!("prompts/: cannot read: {e}"))?;
115	        set.insert(crate::sha256::hex(&crate::sha256::digest(&bytes)));
116	    }
117	    Ok(set)
118	}
