120	/// An `llm` witness is testimony that can only be reproduced from its prompt,
121	/// so it must name one: `prompt=sha256:<digest of a file in prompts/>`, or say
122	/// plainly `prompt=unrecorded`. Other witness kinds are not affected.
123	fn check_witness(witness: &str, prompts: &std::result::Result<BTreeSet<String>, String>) -> std::result::Result<(), String> {
124	    let kind = witness.split([':', ' ']).next().unwrap_or("");
125	    if kind != "llm" {
126	        return Ok(());
127	    }
128	    let need = "an llm witness must name prompt=sha256:<digest of a file in prompts/> or prompt=unrecorded";
129	    let Some(prompt) = witness.split_whitespace().find_map(|t| t.strip_prefix("prompt=")) else {
130	        return Err(format!("{need}: {witness:?}"));
131	    };
132	    if prompt == "unrecorded" {
133	        return Ok(());
134	    }
135	    let Some(hex) = prompt.strip_prefix("sha256:").filter(|h| crate::is_lower_hex(h, 64)) else {
136	        return Err(format!("{need}: {witness:?}"));
137	    };
138	    match prompts {
139	        Err(e) => Err(e.clone()),
140	        Ok(set) if set.contains(hex) => Ok(()),
141	        Ok(_) => Err(format!("prompt=sha256:{hex} names no file in prompts/")),
142	    }
143	}
