145	#[derive(Default)]
146	struct Pending {
147	    statement: String,
148	    witness: String,
149	    rests_on: BTreeSet<String>,
150	    evidence: Vec<Evidence>,
151	    evidence_rows: usize,
152	    first_line: usize,
153	}
