155	#[derive(Default, Debug)]
156	pub struct Outcome {
157	    /// (label, id, statement), sorted by label.
158	    pub claims: Vec<(String, String, String)>,
159	    /// Artifact ids ingested as evidence, sorted.
160	    pub artifacts: Vec<String>,
161	    /// "file:line: problem", in file order.
162	    pub errors: Vec<String>,
163	}
164	
165	pub fn ingest_claims_file(store: &Store, repo_root: &Path, file: &Path) -> Result<Outcome> {
166	    let text = fs::read_to_string(file)?;
167	    let mut pending: BTreeMap<String, Pending> = BTreeMap::new();
168	    let mut out = Outcome::default();
169	    let mut file_cache: BTreeMap<String, std::result::Result<(String, Vec<u8>), String>> = BTreeMap::new();
170	    let mut prompt_digests: Option<std::result::Result<BTreeSet<String>, String>> = None;
171	
172	    for (n, line) in text.lines().enumerate() {
173	        let lineno = n + 1;
174	        if line.is_empty() || line.starts_with('#') {
175	            continue;
176	        }
177	        let err = |out: &mut Outcome, msg: String| out.errors.push(format!("{}:{lineno}: {msg}", file.display()));
178	        let cols: Vec<&str> = line.splitn(6, '\t').collect();
179	        let [label, rests_on, witness, statement, path, quote] = cols[..] else {
180	            err(&mut out, "expected 6 columns: label rests_on witness statement path quote".into());
181	            continue;
182	        };
183	        if label.is_empty() || statement.is_empty() || witness.is_empty() {
184	            err(&mut out, "label, witness and statement must be non-empty".into());
185	            continue;
186	        }
187	        let prompts = prompt_digests.get_or_insert_with(|| prompt_file_digests(repo_root));
188	        if let Err(msg) = check_witness(witness, prompts) {
189	            err(&mut out, msg);
190	            continue;
191	        }
192	        let p = pending.entry(label.to_string()).or_insert_with(|| Pending {
193	            statement: statement.into(),
194	            witness: witness.into(),
195	            first_line: lineno,
196	            ..Default::default()
197	        });
198	        if p.statement != statement || p.witness != witness {
199	            err(&mut out, format!("label {label} reused with a different statement or witness (first on line {})", p.first_line));
200	            continue;
201	        }
202	        if rests_on != "-" {
203	            p.rests_on.extend(rests_on.split(',').map(|s| s.trim().to_string()).filter(|s| !s.is_empty()));
204	        }
205	        if path == "-" && quote == "-" {
206	            continue;
207	        }
208	        p.evidence_rows += 1;
209	        let cached = file_cache.entry(path.to_string()).or_insert_with(|| {
210	            let full = resolve_evidence_path(repo_root, path)?;
211	            let bytes = fs::read(full).map_err(|e| format!("{path}: cannot read: {e}"))?;
212	            let (id, _) = store.ingest(&bytes, path, media_type_for(path)).map_err(|e| format!("{path}: cannot ingest: {e}"))?;
213	            Ok((id, bytes))
214	        });
215	        let (art_id, bytes) = match cached {
216	            Ok(c) => c,
217	            Err(e) => {
218	                err(&mut out, e.clone());
219	                continue;
220	            }
221	        };
222	        let quote = match unescape(quote) {
223	            Ok(q) => q,
224	            Err(e) => {
225	                err(&mut out, e.to_string());
226	                continue;
227	            }
228	        };
229	        match store.evidence_for_quote(art_id, bytes, &quote) {
230	            Ok(ev) => p.evidence.push(ev),
231	            Err(e) => err(&mut out, format!("{e}: {:?}", String::from_utf8_lossy(&quote))),
232	        }
233	    }
234	
235	    // Resolve labels to ids leaves-first. Each pass resolves every claim whose
236	    // dependencies are all resolved; whatever is left is cyclic or broken.
237	    let mut ids: BTreeMap<String, String> = BTreeMap::new();
238	    let mut failed: BTreeSet<String> = BTreeSet::new();
239	    loop {
240	        let mut progressed = false;
241	        for (label, p) in &pending {
242	            if ids.contains_key(label) || failed.contains(label) {
243	                continue;
244	            }
245	            let at = format!("{}:{}", file.display(), p.first_line);
246	            if let Some(bad) = p.rests_on.iter().find(|d| failed.contains(*d) || !pending.contains_key(*d)) {
247	                out.errors.push(format!("{at}: {label} rests on {bad}, which is missing or failed"));
248	                failed.insert(label.clone());
249	                progressed = true;
250	                continue;
251	            }
252	            if !p.rests_on.iter().all(|d| ids.contains_key(d)) {
253	                continue;
254	            }
255	            if p.evidence.is_empty() && (p.evidence_rows > 0 || p.rests_on.is_empty()) {
256	                out.errors.push(format!("{at}: {label} has no surviving evidence"));
257	                failed.insert(label.clone());
258	                progressed = true;
259	                continue;
260	            }
261	            let supports = p.rests_on.iter().map(|d| Link::new(&ids[d])).collect();
262	            let id = store.put_node(&Claim::new(&p.statement, &p.witness, p.evidence.clone(), supports))?;
263	            out.claims.push((label.clone(), id.clone(), p.statement.clone()));
264	            ids.insert(label.clone(), id);
265	            progressed = true;
266	        }
267	        if !progressed {
268	            break;
269	        }
270	    }
271	    for (label, p) in &pending {
272	        if !ids.contains_key(label) && !failed.contains(label) {
273	            out.errors.push(format!("{}:{}: {label} is part of a cycle", file.display(), p.first_line));
274	        }
275	    }
276	
277	    out.claims.sort();
278	    out.artifacts = file_cache.into_values().filter_map(|c| c.ok()).map(|(id, _)| id).collect();
279	    out.artifacts.sort();
280	    out.artifacts.dedup();
281	    Ok(out)
282	}
